638:     void adjust_velocity(ref FlowState fs, ref const(Vector3) my_pos, double omegaz)
639:     {
640:         switch (posMatch) {
641:         case "xyz-to-xyz": /* 3D, do nothing. */ break;
642:         case "xyA-to-xyA": /* 3D, do nothing. */ break;
643:         case "AyA-to-AyA": /* 3D, do nothing. */ break;
644:         case "xy-to-xR": goto case "Ay-to-AR";
645:         case "Ay-to-AR":
646:             // We are assuming that the original 2D simulation had y>0.
647:             double r = sqrt(my_pos.y.re^^2 + my_pos.z.re^^2);
648:             double vel_yz = sqrt(fs.vel.y.re^^2 + fs.vel.z.re^^2);
649:             double vely_sign = (fs.vel.y < 0.0) ? -1.0 : 1.0;
650:             fs.vel.y = vely_sign * vel_yz * my_pos.y.re / r;
651:             fs.vel.z = vely_sign * vel_yz * my_pos.z.re / r;
652:             break;
653:         case "2Daxi-to-3D-rotating":
654:             double axi_vely = sqrt(fs.vel.y.re^^2);
655:             double axi_velx = fs.vel.x.re;
656: 
657:             double cyl_theta = atan2(my_pos.y.re, my_pos.x.re);
658:             double cyl_vel_x = axi_vely*cos(cyl_theta);
659:             double cyl_vel_y = axi_vely*sin(cyl_theta);
660:             double cyl_vel_z = axi_velx;
661: 
662:             fs.vel.x = cyl_vel_x;
663:             fs.vel.y = cyl_vel_y;
664:             fs.vel.z = cyl_vel_z;
665:             break;
666:         default:
667:             throw new FlowSolverException("Invalid match option.");
668:         }
669:         if (omegaz != 0.0) { into_rotating_frame(fs.vel, my_pos, omegaz); }
670:     }
